={
  "system_instruction": {
    "parts": [{
      "text": "Bạn là Intent Classifier cho hệ thống ChatOps Mattermost. Cú pháp hỗ trợ: /agent [project hoặc group] [skill-name] [issueKey], trong đó [project hoặc group] là optional. Phân tích câu lệnh và trả về JSON thuần túy (không dùng markdown code block). Format bắt buộc: {\"intent\": \"standup|run-test|recon|jira|squash|sync|help\", \"params\": {\"project\": \"...\", \"skill\": \"...\", \"issueKey\": \"...\"}}. Mapping intent: run-test (qa-run-test, test, run-test, kiểm thử), standup (daily, standup, sprint), recon (đối chiếu, watchdog, db-timescale-reconciler), jira (vé, issue, ba-spec, ba-refine), sync (đồng bộ, repo-group-sync, pull), squash (qa-squash-push), help (mặc định khi không rõ)."
    }]
  },
  "contents": [{
    "parts": [{
      "text": " Câu lệnh từ Mattermost: " + ($json.body.text || '')
    }]
  }],
  "generationConfig": {
    "temperature": 0.1,
    "maxOutputTokens": 256,
    "responseMimeType": "application/json"
  }
}

parameters.jsCode:
const input = $input.first();
const response = (input && input.json) || {};
const webhookJson = $('Webhook (Mattermost Slash Command)').first()?.json || {};
const webhookBody = webhookJson.body || webhookJson;
const originalText = webhookBody.text || '';
const userName = webhookBody.user_name || '';

function buildAckMessage(intent, params, rawText, user) {
  if (intent === 'help') return '';
  const intentDescriptions = {
    'run-test': `chạy kiểm thử tự động (Pytest) cho ${params?.project ? ('`' + params.project + '` / ') : ''}ticket **${params?.issueKey || 'được yêu cầu'}**`,
    'standup': 'tổng hợp báo cáo **Daily Standup Sprint** và phân tích impediments (>3 ngày)',
    'recon': 'đối chiếu dữ liệu thị trường **KRX MDDS TimescaleDB** (Ticks v3)',
    'jira': `tra cứu và làm sạch thông tin vé Jira **${params?.issueKey || ''}**`,
    'sync': `đồng bộ mã nguồn mới nhất cho ${params?.project ? ('repo `' + params.project + '`') : 'toàn bộ group microservices'}`,
    'squash': 'đẩy danh sách test cases lên **Squash TM**'
  };

  const actionText = intentDescriptions[intent] || 'thực thi tác vụ';
  const userTag = user ? `@${user}` : 'bạn';
  const cleanCmd = (rawText || '').trim();

  return `⏳ **[Agent System]** Đã tiếp nhận lệnh \`/agent ${cleanCmd}\` từ ${userTag}.\n> ⚙️ Hệ thống đang tiến hành **${actionText}**. Quá trình có thể mất từ vài giây đến một phút tùy độ lớn tác vụ, kết quả chi tiết sẽ được gửi tại đây ngay khi hoàn tất. Vui lòng an tâm đợi!`;
}

// ── Hàm bóc tách lệnh theo cú pháp: /agent [project hoặc group] [skill-name] [issueKey] ──
function parseCommand(text) {
  const clean = (text || '').trim();
  if (!clean) return { intent: 'help', params: { project: '', skill: '', issueKey: '' } };

  // 1. Tìm issueKey (pattern: ABC-1234)
  const issueKeyMatch = clean.match(/\b([A-Za-z0-9]+-[0-9]+)\b/i);
  const issueKey = issueKeyMatch ? issueKeyMatch[1].toUpperCase() : '';

  // Bỏ issueKey khỏi chuỗi để phân tích các token còn lại
  let remainder = clean;
  if (issueKeyMatch) {
    remainder = remainder.replace(issueKeyMatch[0], ' ').trim();
  }

  const tokens = remainder.split(/\s+/).filter(Boolean);

  // Mapping skill sang intent
  const skillIntentMap = {
    // QA / Test
    'run-test': 'run-test',
    'qa-run-test': 'run-test',
    'test': 'run-test',
    'kiểm-thử': 'run-test',
    'kiemthu': 'run-test',
    'qa-full-pipeline': 'run-test',
    'qa-auto-design': 'run-test',
    'qa-test-design': 'run-test',

    // Standup / Scrum
    'standup': 'standup',
    'sm-daily-standup': 'standup',
    'daily': 'standup',
    'sm-sprint-planning': 'standup',
    'sm-impediment-triage': 'standup',
    'sm-sprint-retrospective': 'standup',
    'sprint': 'standup',

    // Recon / Database Watchdog
    'recon': 'recon',
    'reconcile': 'recon',
    'db-timescale-reconciler': 'recon',
    'watchdog': 'recon',

    // Jira / BA
    'jira': 'jira',
    'ba-spec': 'jira',
    'ba-refine': 'jira',
    'ba-user-story-writing': 'jira',
    'ba-interview-me': 'jira',
    'ba-gap-analysis': 'jira',

    // Sync
    'sync': 'sync',
    'repo-group-sync': 'sync',
    'pull': 'sync',

    // Squash
    'squash': 'squash',
    'qa-squash-push': 'squash',

    // Help
    'help': 'help'
  };

  let detectedIntent = null;
  let detectedSkill = '';
  let project = '';

  if (tokens.length === 1) {
    const t0 = tokens[0].toLowerCase();
    if (skillIntentMap[t0]) {
      detectedIntent = skillIntentMap[t0];
      detectedSkill = tokens[0];
    } else {
      project = tokens[0];
    }
  } else if (tokens.length >= 2) {
    const t0 = tokens[0].toLowerCase();
    const t1 = tokens[1].toLowerCase();

    if (skillIntentMap[t1]) {
      // Dạng: [project] [skill]
      project = tokens[0];
      detectedSkill = tokens[1];
      detectedIntent = skillIntentMap[t1];
    } else if (skillIntentMap[t0]) {
      // Dạng: [skill] [project]
      detectedSkill = tokens[0];
      detectedIntent = skillIntentMap[t0];
      project = tokens[1];
    } else {
      const skillIdx = tokens.findIndex(t => skillIntentMap[t.toLowerCase()]);
      if (skillIdx !== -1) {
        detectedSkill = tokens[skillIdx];
        detectedIntent = skillIntentMap[detectedSkill.toLowerCase()];
        if (skillIdx > 0) project = tokens[0];
      }
    }
  }

  if (!detectedIntent) {
    const lower = clean.toLowerCase();
    if (lower.includes('test') || lower.includes('kiểm thử')) {
      detectedIntent = 'run-test';
    } else if (issueKey) {
      detectedIntent = 'jira';
    } else if (lower.includes('standup') || lower.includes('daily')) {
      detectedIntent = 'standup';
    } else if (lower.includes('recon')) {
      detectedIntent = 'recon';
    } else if (lower.includes('sync') || lower.includes('pull')) {
      detectedIntent = 'sync';
    } else if (lower.includes('squash')) {
      detectedIntent = 'squash';
    } else {
      detectedIntent = 'help';
    }
  }

  return {
    intent: detectedIntent,
    params: {
      issueKey: issueKey,
      project: project,
      skill: detectedSkill
    }
  };
}

const parsedFallback = parseCommand(originalText);

// Nếu Gemini API gặp lỗi
if (response.error || (response.status && response.status >= 400)) {
  const ackMessage = buildAckMessage(parsedFallback.intent, parsedFallback.params, originalText, userName);
  return [{
    json: {
      ...parsedFallback,
      userName: userName,
      originalCommand: originalText,
      ackMessage: ackMessage,
      _geminiError: response.error?.message || 'Lỗi Gemini API'
    }
  }];
}

try {
  const rawText = response.candidates?.[0]?.content?.parts?.[0]?.text || '';
  let data;
  if (typeof rawText === 'object') {
    data = rawText;
  } else {
    const cleanJson = rawText.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
    data = JSON.parse(cleanJson);
  }

  const validIntents = ['standup', 'run-test', 'recon', 'jira', 'squash', 'sync', 'help'];
  if (!validIntents.includes(data.intent)) {
    data.intent = parsedFallback.intent || 'help';
  }

  data.params = data.params || {};
  if (!data.params.issueKey && parsedFallback.params.issueKey) {
    data.params.issueKey = parsedFallback.params.issueKey;
  }
  if (!data.params.project && parsedFallback.params.project) {
    data.params.project = parsedFallback.params.project;
  }
  if (!data.params.skill && parsedFallback.params.skill) {
    data.params.skill = parsedFallback.params.skill;
  }

  const ackMessage = buildAckMessage(data.intent, data.params, originalText, userName);
  return [{
    json: {
      ...data,
      userName: userName,
      originalCommand: originalText,
      ackMessage: ackMessage
    }
  }];
} catch(e) {
  const ackMessage = buildAckMessage(parsedFallback.intent, parsedFallback.params, originalText, userName);
  return [{
    json: {
      ...parsedFallback,
      userName: userName,
      originalCommand: originalText,
      ackMessage: ackMessage
    }
  }];
}

